// src/core/profile/profile.module.ts

import { FastifyPluginAsync } from 'fastify';
import profileRoutes from './profile.routes';
import commitmentsRoutes from '@modules/profile/commitments.routes';
import pendingResponsibilitiesRoutes from './pending-responsibilities.routes';
import impactOverviewRoutes from './impact-overview.routes';

const profileModule: FastifyPluginAsync = async (fastify) => {
  await fastify.register(profileRoutes);
  await fastify.register(commitmentsRoutes);
  await fastify.register(pendingResponsibilitiesRoutes);
  await fastify.register(impactOverviewRoutes);
};

export default profileModule;
export { profileModule };











